CREATE TABLE student (id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE course (id INTEGER PRIMARY KEY, title TEXT NOT NULL, credit INTEGER);
CREATE TABLE enrollment (
  student_id INTEGER,
  course_id INTEGER,
  score INTEGER,
  PRIMARY KEY (student_id, course_id),
  FOREIGN KEY (student_id) REFERENCES student(id),
  FOREIGN KEY (course_id) REFERENCES course(id)
);
INSERT INTO student VALUES (1, '小明'), (2, '小红');
INSERT INTO course VALUES (101, '数据库', 3), (102, '操作系统', 4);
INSERT INTO enrollment VALUES (1, 101, 88), (1, 102, 76), (2, 101, 95);
SELECT s.name, c.title, e.score
FROM enrollment e
JOIN student s ON s.id = e.student_id
JOIN course c ON c.id = e.course_id
ORDER BY s.name, c.title;
